const words={knowledge:['Knowledge','Знания','知识'],research:['Research','Исследования','研究'],journal:['Journal','Журнал','专栏'],developers:['Developers','Разработчикам','开发者'],wiki:['Wiki','Вики','知识库'],books:['Books','Книги','图书'],repository:['Repository','Репозиторий','版本库'],docs:['Documentation','Документация','文档'],search:['Search','Поиск','搜索'],menu:['Menu','Меню','菜单'],close:['Close','Закрыть','关闭'],home:['Home','Главная','首页'],explore:['Explore knowledge','Изучить знания','探索知识'],readResearch:['Read research','Читать исследования','浏览研究'],heroLabel:['A place for connected knowledge','Пространство связанных знаний','连接知识的空间'],heroTitle:['Knowledge, with a traceable foundation.','Знания, у которых есть основания.','让知识有据可循。'],heroDesc:['Ideas become more useful when you can follow where they came from. Explore knowledge connected to its sources, context and history.','Идеи полезнее, когда понятно, откуда они появились. Изучайте знания в связи с их источниками, контекстом и историей.','当我们能追溯想法的来源时，知识就更有价值。探索知识与其来源、背景和历史之间的联系。'],heroNote:['An evolving library. Built for reading, understanding and building.','Развивающаяся библиотека. Для чтения, понимания и созидания.','持续生长的知识库，为阅读、理解与创造而建。'],source:['Source','Источник','来源'],concept:['Concept','Понятие','概念'],context:['Context','Контекст','背景'],revision:['Revision','Версия','版本'],history:['History','История','历史'],knowledgeObject:['Knowledge object','Объект знания','知识对象'],connected:['Connected, not isolated','Связано, не изолировано','连接，而非孤立'],graphCaption:['An illustration of the knowledge contract','Иллюстрация контракта знаний','知识契约的示意图'],pathKnowledge:['Follow ideas through concepts, books and their sources.','Связывайте понятия, книги и их источники.','沿着概念、图书与来源探索想法。'],pathResearch:['Find the work behind the ideas. Read it in context.','Находите работы, стоящие за идеями.','找到想法背后的研究，并理解其背景。'],pathBuild:['Understand the structure. Build on clear foundations.','Разбирайтесь в структуре. Стройте на ясной основе.','理解知识结构，在清晰的基础上构建。'],startHere:['Start with an idea','Начните с идеи','从一个想法开始'],viewWiki:['Browse the wiki','Открыть вики','浏览知识库'],designExample:['Illustrative concept','Пример концепции','概念示例'],featureTitle:['A contract between knowledge and its sources.','Контракт между знанием и его источниками.','知识与来源之间的契约。'],featureDesc:['A claim is a beginning, not an endpoint. A knowledge contract makes its evidence, context and revisions visible alongside it.','Утверждение — начало, а не конечная точка. Контракт знаний делает видимыми его основания, контекст и изменения.','主张只是起点。知识契约让证据、背景和修订与知识本身一同呈现。'],readConcept:['Read the concept','Читать о концепции','阅读概念'],projectConcept:['Project concept','Концепция проекта','项目概念'],sourceCount:['Design kit v1','Дизайн-комплект v1','设计套件 v1'],waysTitle:['Different ways in. One connected library.','Разные пути. Одна библиотека.','多种探索方式，同一座知识库。'],waysDesc:['Move from a first question to a deeper understanding.','От первого вопроса к глубокому пониманию.','从最初的疑问，走向更深入的理解。'],wikiDesc:['Clear definitions, linked ideas and the sources behind them.','Ясные определения, связанные идеи и их источники.','清晰的定义、相互关联的想法及其来源。'],booksDesc:['A quiet space for long-form reading, editions and chapters.','Место для вдумчивого чтения, изданий и глав.','为长篇阅读、版本与章节留出安静的空间。'],repositoryDesc:['Trace what changed, when it changed and where it came from.','Узнавайте, что изменилось, когда и почему.','追溯变化的内容、时间与来源。'],browseConcepts:['Browse concepts','Найти понятия','浏览概念'],viewLibrary:['View the library','Открыть библиотеку','查看图书馆'],traceChanges:['Trace changes','Изучить изменения','追踪变化'],buildTitle:['Good foundations are meant to be built on.','На хорошей основе можно строить.','好的基础，值得继续构建。'],buildDesc:['Start with the knowledge model: a clear identity, explicit sources and a visible revision. Read how this space works.','Начните с модели знаний: ясная идентичность, явные источники и видимая версия. Узнайте, как устроено это пространство.','从知识模型开始：清晰的标识、明确的来源和可见的版本。了解这个空间如何运作。'],readDocs:['Read the documentation','Читать документацию','阅读文档'],exampleSchema:['Illustrative knowledge model','Пример модели знаний','知识模型示例'],notEndpoint:['An example data shape. No live API or MCP server is connected.','Пример структуры данных. API и MCP ещё не подключены.','示例数据结构。尚未连接 API 或 MCP 服务。'],copy:['Copy example','Скопировать пример','复制示例'],copied:['Copied','Скопировано','已复制'],copyFailed:['Copy unavailable. Select the example text to copy.','Копирование недоступно. Выделите текст примера вручную.','无法复制。请手动选择示例文本。'],fromJournal:['From the journal','Из журнала','来自专栏'],allEntries:['View all entries','Все записи','查看所有文章'],projectUpdate:['Project update','Обновление проекта','项目动态'],journalTitle:['Building a place for traceable knowledge','Создаём пространство прослеживаемых знаний','为可追溯的知识构建空间'],journalDesc:['Notes on the structure, design and development of contract.place.','Заметки о структуре, дизайне и развитии contract.place.','关于 contract.place 结构、设计和发展的记录。'],closingTitle:['Follow the idea. Find the source.','Следуйте за идеей. Находите источник.','顺着想法，找到来源。'],closingDesc:['Start exploring a more connected way to read.','Откройте связанный подход к чтению.','开始探索更有联系的阅读方式。'],tagline:['Knowledge, connected to its foundations.','Знания, связанные с основаниями.','让知识连接其根基。'],footerNote:['A first edition of contract.place.','Первое издание contract.place.','contract.place 的初始版本。'],privacy:['Preferences are stored only in your browser.','Настройки сохраняются только в вашем браузере.','偏好设置仅保存在您的浏览器中。'],references:['References','Референсы','参考来源'],researchIntro:['Explore the research spaces and documentation that informed contract.place.','Исследовательские пространства и документация, которые легли в основу contract.place.','探索启发 contract.place 的研究空间与文档。'],referenceNotice:['This is the design reference collection, not a catalog of original contract.place research. Original publications have not been provided.','Это коллекция дизайн-референсов, а не каталог собственных исследований contract.place. Оригинальные публикации пока не предоставлены.','这是设计参考集合，并非 contract.place 原创研究目录。尚未提供原创出版物。'],all:['All','Все','全部'],documentation:['Documentation','Документация','文档'],findReference:['Find a reference…','Найти референс…','查找参考来源…'],noResults:['No matching results','Подходящих результатов нет','未找到匹配结果'],clear:['Clear filters','Сбросить фильтры','清除筛选'],openSource:['Open original source','Открыть источник','打开原始来源'],editorialNotice:['The following article is available in English. Interface controls remain in your selected language.','Статья доступна на английском. Элементы интерфейса остаются на выбранном языке.','以下文章提供英文版本。界面控件保持您选择的语言。'],wikiIntro:['A small starting collection of concepts behind this space. Each entry is an original explanatory example, grounded in the supplied design kit.','Небольшая коллекция понятий, на которых основано это пространство. Каждая статья — поясняющий пример по дизайн-комплекту.','从支撑这个空间的概念开始。每个条目都是基于所提供设计套件编写的解释性示例。'],booksIntro:['Long-form knowledge, with its context intact.','Глубокое чтение с сохранением контекста.','完整保留背景的长篇知识。'],noBooks:['The first shelf is still being curated.','Первая полка ещё формируется.','第一排书架正在整理中。'],noBooksDesc:['No books or redistribution licenses were included in the project materials. Until the first titles are added, explore the foundational concepts in the wiki.','В материалах проекта пока нет книг и лицензий на их распространение. До появления первых изданий можно изучить базовые понятия в вики.','项目材料中尚未包含图书或再分发许可。在首批书目加入之前，欢迎先探索知识库中的基础概念。'],repositoryIntro:['A record of the materials this site is built on.','История материалов, на которых построен сайт.','记录构建本站所依据的材料。'],kitTitle:['contract.place design kit','Дизайн-комплект contract.place','contract.place 设计套件'],kitDesc:['The original identity and interface specification supplied for this site.','Оригинальная айдентика и спецификация интерфейса, предоставленные для создания сайта.','为本站提供的原始品牌标识与界面规范。'],viewHistory:['View version history','Посмотреть историю','查看版本历史'],current:['Current source edition','Текущая редакция исходников','当前来源版本'],singleRevision:['One source edition is available. A comparison will be possible when another edition is added.','Доступна одна редакция исходников. Сравнение появится после добавления следующей.','目前只有一个来源版本。新增版本后即可进行比较。'],openKit:['Open the source design kit','Открыть дизайн-комплект','打开设计套件'],gettingStarted:['Getting started','Начало работы','入门'],knowledgeModel:['Knowledge model','Модель знаний','知识模型'],availability:['Integration availability','Доступность интеграций','集成可用性'],docsIntro:['Find a concept, follow its sources and understand the edition you are reading.','Находите понятия, изучайте источники и проверяйте редакцию, которую читаете.','查找概念、追踪来源，并了解您正在阅读的版本。'],step1:['Find your starting point','Найдите отправную точку','找到起点'],step1Desc:['Browse the wiki for foundational concepts, or open the reference collection to explore the sites that informed this project.','Изучите базовые понятия в вики или откройте коллекцию референсов проекта.','在知识库中浏览基础概念，或打开参考集合，探索启发本项目的网站。'],step2:['Follow the provenance','Проверьте происхождение','追踪来源'],step2Desc:['Concept pages separate explanatory text from source material. Open the Sources section to see what an entry is based on.','Страницы понятий отделяют поясняющий текст от исходных материалов. Раздел «Источники» показывает, на чём основана статья.','概念页面区分解释性文字和原始材料。打开“来源”部分，了解条目的依据。'],step3:['Choose how you read','Настройте чтение','选择阅读方式'],step3Desc:['Switch between light and dark themes. Choose English, Russian or Simplified Chinese from the language selector. Your current page is preserved.','Переключайтесь между светлой и тёмной темами. Выберите английский, русский или китайский язык. Текущая страница сохранится.','可切换浅色与深色主题，并选择英语、俄语或简体中文。切换时会保留当前页面。'],localSearch:['Search this collection','Поиск по коллекции','搜索本集合'],localSearchDesc:['Use Search or ⌘/Ctrl K. Search works on the collection included with this site and does not send your query to an external service.','Нажмите «Поиск» или ⌘/Ctrl K. Поиск работает по материалам сайта и не отправляет запрос во внешние сервисы.','使用搜索或 ⌘/Ctrl K。搜索仅针对本站集合，不会将查询发送到外部服务。'],notConnected:['Not connected','Не подключено','尚未连接'],apiDesc:['No production endpoint or authentication contract has been supplied.','Рабочий адрес API и схема авторизации не предоставлены.','尚未提供生产端点或身份验证规范。'],mcpDesc:['No server capabilities or connection settings have been supplied.','Возможности сервера и параметры подключения не предоставлены.','尚未提供服务器能力或连接设置。'],accountDesc:['Accounts and cloud-saved reading are not enabled.','Аккаунты и облачное сохранение чтения не включены.','账户及云端阅读收藏尚未启用。'],account:['Accounts','Аккаунты','账户'],available:['Available','Доступно','可用'],browserFeatures:['Reading, local search, language and theme preferences','Чтение, поиск, выбор языка и темы','阅读、本地搜索、语言和主题偏好'],sources:['Sources','Источники','来源'],article:['Article','Статья','文章'],edition:['Edition','Редакция','版本'],english:['Read in English','Читать на английском','阅读英文版'],searchPlaceholder:['Search concepts, references and guides…','Искать понятия, референсы и руководства…','搜索概念、参考来源与指南…'],searchHint:['Search the site collection. Press Esc to close.','Поиск по материалам сайта. Нажмите Esc, чтобы закрыть.','搜索本站集合。按 Esc 关闭。'],searchStart:['Start with “knowledge”, “sources” or “design”.','Попробуйте «знания», «источники» или «дизайн».','试试“知识”、“来源”或“设计”。'],light:['Switch to light theme','Включить светлую тему','切换为浅色主题'],dark:['Switch to dark theme','Включить тёмную тему','切换为深色主题'],language:['Language','Язык','语言'],skip:['Skip to main content','Перейти к содержимому','跳转至主要内容'],notFound:['This page could not be found.','Страница не найдена.','未找到此页面。'],backHome:['Back to home','На главную','返回首页'],readEntry:['Read entry','Читать запись','阅读文章'],searchResults:['Search results','Результаты поиска','搜索结果'],cookieSettings:['Cookie settings','Настройки cookie','Cookie 设置'],analyticsTitle:['Analytics and cookies','Аналитика и cookie','分析与 Cookie'],analyticsBody:['This site uses Google Analytics 4 to measure how the published documents are read. The Google tag is loaded only after you accept analytics in the cookie banner; until then no request reaches Google. Your choice is stored in this browser and can be changed at any time from the footer.','Сайт использует Google Analytics 4, чтобы измерить, как читают опубликованные документы. Тег Google загружается только после того, как вы примете аналитику в баннере cookie; до этого ни один запрос не уходит в Google. Ваш выбор хранится в этом браузере, его можно изменить в любой момент в подвале сайта.','本网站使用 Google Analytics 4 衡量已发布文档的阅读情况。只有在您在 Cookie 横幅中接受分析之后，才会加载 Google 标签；在此之前不会有任何请求发往 Google。您的选择保存在此浏览器中，可随时在页脚更改。']};
let locale='en';const langs=['en','ru','zh-Hans'];const t=k=>(words[k]||[k,k,k])[langs.indexOf(locale)];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const url=path=>`/${locale}/${path?path+'/':''}`;const link=(path,label,cls='text-link',ico='arrow')=>`<a class="${cls}" href="${url(path)}">${label}${ico?icon(ico):''}</a>`;const date=()=>new Intl.DateTimeFormat(locale,{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date('2026-11-04T12:00:00Z'));
const brand=()=>`<a class="brand brand-v2" href="${url('')}" aria-label="contract.place"><svg class="brand-symbol" viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M28.5 8C18-1 3 7 6.5 21.5 8.5 30 21 34 28.5 25" stroke="currentColor" stroke-width="4.4" stroke-linecap="round"/><path d="M11.5 15C19 6 31.5 10 33.5 18.5 37 33 22 41 11.5 32" stroke="var(--teal)" stroke-width="4.4" stroke-linecap="round"/></svg><span class="wordmark">contract<span class="brand-period">.</span>place</span></a>`;
const mark=()=>`<img class="light-logo" src="/assets/mark.svg" alt="" width="42" height="42"><img class="dark-logo" src="/assets/mark-dark.svg" alt="" width="42" height="42">`;
const languageNames=['English','Русский','简体中文'];
const flag=(lang)=>{const shapes={en:'<path fill="#214477" d="M0 0h30v20H0z"/><path stroke="#fff" stroke-width="5" d="m0 0 30 20M30 0 0 20"/><path stroke="#c43c47" stroke-width="2" d="m0 0 30 20M30 0 0 20"/><path fill="#fff" d="M12 0h6v20h-6zM0 6h30v8H0z"/><path fill="#c43c47" d="M13 0h4v20h-4zM0 8h30v4H0z"/>',ru:'<path fill="#fff" d="M0 0h30v20H0z"/><path fill="#2855a4" d="M0 6.667h30v6.667H0z"/><path fill="#c83e43" d="M0 13.333h30V20H0z"/>','zh-Hans':'<path fill="#d73835" d="M0 0h30v20H0z"/><path fill="#ffe078" d="m7 3 1.1 3.3h3.5L8.8 8.4l1.1 3.3L7 9.7l-2.9 2 1.1-3.3-2.8-2.1h3.5z"/><g fill="#ffe078"><path d="m14 2 .4 1.1h1.2l-.9.7.3 1.2-1-.7-.9.7.3-1.2-.9-.7h1.2zM17 5l.4 1.1h1.2l-.9.7.3 1.2-1-.7-.9.7.3-1.2-.9-.7h1.2zM17 10l.4 1.1h1.2l-.9.7.3 1.2-1-.7-.9.7.3-1.2-.9-.7h1.2zM14 13l.4 1.1h1.2l-.9.7.3 1.2-1-.7-.9.7.3-1.2-.9-.7h1.2z"/></g>'};return `<svg class="language-flag" viewBox="0 0 30 20" aria-hidden="true" focusable="false">${shapes[lang]}</svg>`};
const localeSelect=()=>`<details class="language-picker"><summary class="locale-trigger" aria-label="${t('language')}: ${languageNames[langs.indexOf(locale)]}">${flag(locale)}<span class="locale-name">${languageNames[langs.indexOf(locale)]}</span>${icon('chevron')}</summary><div class="locale-panel" aria-label="${t('language')}">${langs.map((l,i)=>`<button type="button" class="locale-option" data-locale="${l}" lang="${l}" aria-pressed="${l===locale}">${flag(l)}<span>${languageNames[i]}</span><span class="locale-check" aria-hidden="true">${l===locale?icon('check'):''}</span></button>`).join('')}</div></details>`;
const themeBtn=()=>`<button class="icon-btn theme-btn" aria-label="${t(document.documentElement.dataset.theme==='dark'?'light':'dark')}">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button>`;
const refs=[{id:'anthropic',name:'Anthropic Research',type:'research',org:'Anthropic',source:'https://www.anthropic.com/research',desc:['Research organized around clear disciplines, thoughtful introductions and an accessible archive.','Исследования с понятным делением на дисциплины, вводными текстами и доступным архивом.','以清晰的学科分类、深入浅出的介绍和易于浏览的档案组织研究。']},{id:'deepmind',name:'Google DeepMind Research',type:'research',org:'Google DeepMind',source:'https://deepmind.google/research/',desc:['A layered approach to exploring research, models and the relationship between AI and science.','Многоуровневая навигация по исследованиям, моделям и связям ИИ с наукой.','通过分层导航探索研究、模型，以及人工智能与科学的联系。']},{id:'hugging-face',name:'Hugging Face Papers',type:'research',org:'Hugging Face',source:'https://huggingface.co/papers',desc:['A compact research feed that puts paper titles, dates and contributors within easy reach.','Компактная лента научных работ с названиями, датами и авторами.','紧凑的论文信息流，让标题、日期和贡献者一目了然。']},{id:'mcp',name:'Model Context Protocol',type:'documentation',org:'Model Context Protocol',source:'https://modelcontextprotocol.io/docs/getting-started/intro',desc:['Concepts, introductory guides and specification material presented as distinct reading paths.','Понятия, вводные руководства и спецификация как отдельные пути чтения.','将概念、入门指南与规范作为不同的阅读路径。']},{id:'stripe',name:'Stripe Documentation',type:'documentation',org:'Stripe',source:'https://docs.stripe.com/',desc:['Task-led documentation with consistent examples and clearly structured reference material.','Документация от задач пользователя к примерам и структурированному справочнику.','以任务为导向的文档，配合一致的示例与清晰的参考结构。']},{id:'supabase',name:'Supabase Docs',type:'documentation',org:'Supabase',source:'https://supabase.com/docs',desc:['A clear progression from a first quickstart to platform concepts and detailed references.','Ясный путь от первого примера к понятиям платформы и подробным справочникам.','从快速入门逐步深入平台概念与详细参考。']}];
const concepts=[{id:'knowledge-contract',title:['The knowledge contract','Контракт знаний','知识契约'],desc:['An explicit connection between a claim, its sources and the history of its revisions.','Явная связь утверждения с источниками и историей его изменений.','将主张、来源与修订历史明确联系起来。'],body:`<p>A knowledge contract is the organizing idea behind contract.place: a visible agreement between a piece of knowledge, the sources it relies on and the history of how it has changed.</p><p>This is a project concept, not a published or certified standard. It describes how this library intends to present information.</p><h2 id="structure">A claim with its context intact</h2><p>A statement becomes easier to evaluate when its context travels with it. A reader should be able to identify what is being claimed, where the supporting material comes from, and which edition they are reading.</p><blockquote>Make the connection visible, so the reader can follow it.</blockquote><h2>What belongs beside an idea?</h2><ul><li>A stable identity that remains recognizable as the text changes.</li><li>A clear distinction between explanation, source material and interpretation.</li><li>Explicit source links and a visible revision.</li><li>A history that describes material changes without implying independent verification.</li></ul><h2>Where this example stops</h2><p>This page illustrates the concept using the supplied design specification. It does not establish a legal agreement, validate research findings, or demonstrate a working API.</p>`},{id:'provenance',title:['Provenance','Происхождение знаний','知识溯源'],desc:['Understand where a piece of knowledge came from, and what it is based on.','Узнайте, откуда появилось знание и на чём оно основано.','了解知识从何而来，以及它的依据。'],body:`<p>Provenance is the record of where an item came from and the context surrounding its creation. In this project, it means making sources, authorship and revision information visible alongside the content.</p><h2>Follow the source</h2><p>A source link lets a reader leave an editorial explanation and inspect its basis. A visible reference is useful context; it is not by itself evidence that every claim has been independently checked.</p><h2>Separate the layers</h2><p>Original material, summaries and interpretations should be distinguishable. This site labels its concept entries as illustrative explanations and its reference collection as design sources.</p><h2>Keep the limits visible</h2><p>When the underlying record is incomplete, the page should say so. Missing authors, publication dates or verification records should remain missing rather than being invented for a more complete-looking interface.</p>`},{id:'versioned-knowledge',title:['Versioned knowledge','Версии знаний','知识版本'],desc:['Read an idea as a particular edition, with a visible record of meaningful changes.','Читайте конкретную редакцию идеи с историей значимых изменений.','阅读知识的特定版本，并查看重要变化的记录。'],body:`<p>Ideas and explanations change. A version makes it possible to identify a particular edition instead of treating the current text as though it has always existed.</p><h2>A stable object, a changing edition</h2><p>The content identity stays stable while revisions describe changes. A useful history connects each edition to its date, source and change summary.</p><h2>Compare only what exists</h2><p>A comparison requires two actual editions. The supplied contract.place design kit contains one source edition, so the repository shows that edition and does not invent an earlier version or a synthetic history.</p><h2>Version does not mean verified</h2><p>A revision identifier describes identity and sequence. It does not certify the truth of an idea or replace a review of its supporting evidence.</p>`}];
const translated=arr=>arr[langs.indexOf(locale)];
function header(path){return `<div class="container header-inner">${brand()}<nav class="desktop-nav" aria-label="${t('menu')}"><details class="nav-group"><summary class="nav-item">${t('knowledge')}${icon('chevron')}</summary><div class="popover">${link('wiki',`${t('wiki')}<small>${t('wikiDesc')}</small>`,'','')}${link('books',`${t('books')}<small>${t('booksDesc')}</small>`,'','')}${link('repository',`${t('repository')}<small>${t('repositoryDesc')}</small>`,'','')}</div></details>${(corpus.programme?['research','programme','roadmap','journal']:['research','roadmap','journal']).map(x=>`<a class="nav-item" href="${url(x)}" ${path.startsWith(x)?'aria-current="page"':''}>${t(x)}</a>`).join('')}<details class="nav-group"><summary class="nav-item">${t('developers')}${icon('chevron')}</summary><div class="popover">${link('docs',t('docs'),'','')}${link('docs/availability',t('availability'),'','')}</div></details></nav><div class="utilities"><button class="search-trigger" data-search aria-label="${t('search')}">${icon('search')}<span>${t('search')}</span><kbd>⌘ K</kbd></button>${localeSelect()}${themeBtn()}<button class="icon-btn mobile-menu" data-menu aria-label="${t('menu')}">${icon('menu')}</button></div></div>`}
function footer(){return `<div class="container"><div class="footer-grid"><div class="footer-brand">${brand()}<p>${t('tagline')}</p></div><div class="footer-group"><strong>${t('knowledge')}</strong>${link('reference',t('reference'),'','')}${link('appendices',t('appendices'),'','')}${link('books',t('books'),'','')}${link('repository',t('repository'),'','')}</div><div class="footer-group"><strong>${t('research')}</strong>${link('research',t('references'),'','')}${link('journal',t('journal'),'','')}</div><div class="footer-group"><strong>${t('developers')}</strong>${link('docs',t('docs'),'','')}${link('docs/availability',t('availability'),'','')}</div></div><div class="footer-bottom"><span>© 2026 contract.place &nbsp; ${t('footerNote')}</span><span>${t('privacy')}</span></div></div>`}
function graph(){return `<div class="graph" role="img" aria-label="${t('graphCaption')}"><svg class="graph-lines" viewBox="0 0 550 410" preserveAspectRatio="none" aria-hidden="true"><path d="M110 70H200V180M465 125H400V180M100 335H200V260M465 345H400V260"/><path class="active-line" d="M275 60V150M275 280V355"/><circle cx="275" cy="60" r="4" fill="var(--teal)"/><circle cx="275" cy="355" r="4" fill="var(--teal)"/></svg><div class="graph-node source1">${icon('file')}${t('source')}</div><div class="graph-node source2">${icon('layers')}${t('context')}</div><div class="graph-main">${mark()}<div><strong>${t('knowledgeObject')}</strong><small>${t('connected')}</small></div></div><div class="graph-node source3">${icon('branch')}${t('revision')} 1.0</div><div class="graph-node source4">${icon('book')}${t('concept')}</div><div class="graph-caption">${t('graphCaption')}</div></div>`}
const example={id:'knowledge-contract',type:'concept',revision:'1.0',sources:['design-kit-v1']};
function codeBlock(){return `<div class="code-window"><div class="code-heading"><span>knowledge-contract.json</span><button class="icon-btn" data-copy aria-label="${t('copy')}">${icon('copy')}</button></div><pre><code>{
  <span class="code-key">"id"</span>: <span class="code-value">"knowledge-contract"</span>,
  <span class="code-key">"type"</span>: <span class="code-value">"concept"</span>,
  <span class="code-key">"revision"</span>: <span class="code-value">"1.0"</span>,
  <span class="code-key">"sources"</span>: [<span class="code-value">"design-kit-v1"</span>]
}</code></pre><div class="code-note">${t('notEndpoint')}</div></div>`}
function pageHead(title,desc){return `<div class="page-head"><div class="breadcrumb">${link('',t('home'),'','')}<span>/</span><span>${title}</span></div><h1>${title}</h1>${desc?`<p class="lead">${desc}</p>`:''}</div>`}
function filterButton(value,label,active){return `<button class="filter-button" data-filter="${value}" aria-pressed="${value===active}">${label}</button>`}
function article(c){return `<article class="container reading">${pageHead(translated(c.title),translated(c.desc))}<span class="tag">${t('designExample')}</span><div class="provenance metadata"><span>contract.place</span><span>${t('revision')} 1.0</span><span>${t('sourceCount')}</span></div>${locale!=='en'?`<p class="intro-note">${t('editorialNotice')} ${link('wiki/'+c.id,t('english'),'','')}</p>`:''}<nav class="article-tabs" aria-label="${t('article')}"><a href="#article">${t('article')}</a></nav><div id="article" lang="en">${c.body}</div>${link('wiki',t('viewWiki'))}</article>`}
function researchDetail(r){return `<article class="container reading">${pageHead(r.name,translated(r.desc))}<div class="provenance metadata"><span>${r.org}</span><span>${t('references')}</span><span>${t(r.type)}</span></div><p class="intro-note">${t('referenceNotice')}</p><h2>${t('context')}</h2><p>${translated(r.desc)}</p><p>${translated(['Included as a reference in the supplied contract.place design audit. This entry describes the design pattern that informed the project; it does not reproduce the source site or claim an affiliation.','Включён в аудит референсов из дизайн-комплекта contract.place. Запись описывает принципы, повлиявшие на проект, и не означает партнёрство с источником.','此来源收录于所提供的 contract.place 设计参考审查中。本条目描述对项目产生启发的设计模式，并不表示与来源网站有关联。'])}</p><a class="button" href="${r.source}" target="_blank" rel="noopener">${t('openSource')}${icon('external')}</a><h2>${t('sources')}</h2><ul class="source-list"><li><a href="${r.source}" target="_blank" rel="noopener">${r.name} ${icon('external')}</a></li></ul>${link('research',t('references'))}</article>`}
function books(){return `<div class="container">${pageHead(t('books'),t('booksIntro'))}<div class="empty"><div class="card-icon">${icon('book')}</div><h2>${t('noBooks')}</h2><p>${t('noBooksDesc')}</p>${link('wiki',t('browseConcepts'),'button')}</div></div>`}
function journal(){return `<div class="container">${pageHead(t('journal'),t('journalDesc'))}<div class="records"><a class="record" href="${url('journal/building-a-place')}"><div><span class="tag">${t('projectUpdate')}</span><h2>${t('journalTitle')}</h2><p>${t('tagline')}</p><div class="metadata"><span>contract.place</span><time datetime="2026-11-04">${date()}</time></div></div>${icon('arrow')}</a></div></div>`}
function journalArticle(){return `<article class="container reading">${pageHead(t('journalTitle'),t('journalDesc'))}<div class="provenance metadata"><span>${t('projectUpdate')}</span><span>contract.place</span><time datetime="2026-11-04">${date()}</time></div>${locale!=='en'?`<p class="intro-note">${t('editorialNotice')}</p>`:''}<div lang="en"><p>This first edition turns the supplied contract.place design system into a place you can explore. Its organizing idea is simple: knowledge should stay connected to its sources, its context and its history.</p><h2>A library with room to grow</h2><p>The wiki starts with three illustrative concepts. The research section contains the six design references from the original brief. The books section is ready for a real, licensed collection; no titles have been invented to fill it.</p><h2>One identity, different ways to read</h2><p>The original bracket-and-connection mark anchors a quiet reading environment. Warm paper, deep ink and teal come directly from the design kit. Light and dark themes share the same structure.</p><h2>Be clear about what exists</h2><p>Search runs on the collection included with this site. Language and theme preferences stay in your browser. API, MCP and account services are not connected, and their availability is stated in the documentation.</p><h2>What comes next</h2><p>A real publication corpus, approved translations and licensed book editions will give this structure its depth. Those materials can be added without inventing a new identity or navigation system.</p></div>${link('wiki',t('explore'))}</article>`}
function docs(path){const section=path.split('/')[1]||'getting-started';return `<div class="container docs-layout"><nav class="docs-nav" aria-label="${t('docs')}"><strong>${t('docs')}</strong>${[['','gettingStarted'],['model','knowledgeModel'],['availability','availability']].map(([p,l])=>`<a href="${url('docs'+(p?'/'+p:''))}" ${section===(p||'getting-started')?'aria-current="page"':''}>${t(l)}</a>`).join('')}</nav><article class="docs-article">${section==='getting-started'?`<h1>${t('gettingStarted')}</h1><p class="lead">${t('docsIntro')}</p>${[['step1','step1Desc','wiki','browseConcepts'],['step2','step2Desc','wiki/provenance','readConcept'],['step3','step3Desc',null,null]].map(([title,desc,p,a])=>`<section class="step"><h2>${t(title)}</h2><p>${t(desc)}</p>${p?link(p,t(a)):''}</section>`).join('')}<section class="step"><h2>${t('localSearch')}</h2><p>${t('localSearchDesc')}</p><button class="button" data-search>${icon('search')}${t('search')}</button></section>`:section==='model'?`<h1>${t('knowledgeModel')}</h1><p class="lead">${t('featureDesc')}</p><p class="intro-note">${t('designExample')}</p>${codeBlock()}<h2>${t('source')}</h2><p>${t('wikiDesc')}</p>${link('wiki/knowledge-contract',t('readConcept'))}<h2>${t('revision')}</h2><p>${t('repositoryDesc')}</p>${link('wiki/versioned-knowledge',t('readConcept'))}`:`<h1>${t('availability')}</h1><p class="lead">${t('notEndpoint')}</p><div class="status-row"><div><strong>${t('browserFeatures')}</strong><small>${t('localSearchDesc')}</small></div><span class="tag">${t('available')}</span></div>${[['API','apiDesc'],['MCP','mcpDesc'],[t('account'),'accountDesc']].map(([title,d])=>`<div class="status-row"><div><strong>${title}</strong><small>${t(d)}</small></div><span class="status">${t('notConnected')}</span></div>`).join('')}`}</article></div>`}
function normalize(s){return s.normalize('NFKC').toLocaleLowerCase(locale).trim()}
function searchResults(q){const results=searchItems(q);return results.length?results.map(r=>`<a class="dialog-result" href="${url(r.path)}"><strong>${esc(r.title)}</strong><small>${esc(r.type)}${r.badge||''}</small></a>`).join(''):`<p>${t('noResults')}</p>`}
function searchPage(){const q=new URLSearchParams(location.search).get('q')||'';return `<div class="container">${pageHead(t('searchResults'),'')}<form id="page-search-form"><input class="search-input" name="q" type="search" value="${esc(q)}" aria-label="${t('search')}" placeholder="${t('searchPlaceholder')}"><button class="button">${t('search')}</button></form><div class="records">${searchResults(q)}</div>${documentSearch()}</div>`}
function documentSearch(){return `<section class="doc-search" id="document-search" data-publication-repository="${corpus.publication.repository}" data-publication-commit="${corpus.publication.commit}" data-publication-edition="${corpus.publication.edition}" aria-labelledby="doc-search-title"><h2 id="doc-search-title">${t('publicSearch')}</h2><p>${translated(['Searches the full text of the published documents through the public read API. Results keep the order the API returns; no relevance threshold is claimed.','Ищет по полному тексту опубликованных документов через публичный API. Порядок результатов — как его отдаёт API; порог релевантности не заявляется.','通过公共只读 API 检索已发布文档全文。结果顺序与 API 返回一致，不声明相关性阈值。'])}</p><form id="search-form" hidden><label class="sr-only" for="search-q">${t('publicSearch')}</label><input class="search-input" id="search-q" type="search" maxlength="256" autocomplete="off" placeholder="${translated(['Search the text of published documents…','Поиск по тексту опубликованных документов…','搜索已发布文档全文…'])}"><button class="button" type="submit">${t('search')}</button></form><noscript><p class="intro-note">${translated(['Document search needs JavaScript. You can also query the public read API directly: https://api.contract.place/v1/search?q=knowledge','Для поиска по документам нужен JavaScript. Можно обратиться к публичному API напрямую: https://api.contract.place/v1/search?q=knowledge','文档搜索需要 JavaScript。也可以直接访问公共 API：https://api.contract.place/v1/search?q=knowledge'])}</p></noscript><p id="search-status" role="status" aria-live="polite"></p><ol id="search-results" class="doc-results"></ol><button class="button" id="search-more" type="button" hidden>${translated(['More results','Ещё результаты','更多结果'])}</button></section>`}
let lastTrigger=null;
function openSearch(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.querySelectorAll('details[open]').forEach(d=>d.open=false);lastTrigger=document.activeElement;const d=document.querySelector('#search-dialog');d.innerHTML=`<div class="dialog-head"><h2 id="search-title">${t('search')}</h2><button class="icon-btn" data-close aria-label="${t('close')}">${icon('close')}</button></div><div class="dialog-content"><label class="sr-only" for="global-search">${t('search')}</label><input class="search-input" id="global-search" type="search" placeholder="${t('searchPlaceholder')}" autocomplete="off"><div class="dialog-results" id="global-results"><p>${t('searchStart')}</p>${searchResults('')}</div><p class="dialog-tip">${t('searchHint')}</p><span class="sr-only" id="search-announcement" aria-live="polite"></span></div>`;d.showModal();d.querySelector('input').focus();d.querySelector('input').addEventListener('input',e=>{if(e.isComposing)return;updateSearch(e.target.value)});d.querySelector('input').addEventListener('compositionend',e=>updateSearch(e.target.value));d.querySelector('input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing){d.close();navigate(url('search')+'?q='+encodeURIComponent(e.target.value))}})}
function updateSearch(q){document.querySelector('#global-results').innerHTML=searchResults(q);document.querySelector('#search-announcement').textContent=String(searchItems(q).length)}
function openMenu(){document.querySelectorAll('details[open]').forEach(d=>d.open=false);document.querySelectorAll('dialog[open]').forEach(d=>d.close());lastTrigger=document.activeElement;const d=document.querySelector('#menu-dialog');d.innerHTML=`<div class="dialog-head"><h2>${t('menu')}</h2><button class="icon-btn" data-close aria-label="${t('close')}">${icon('close')}</button></div><div class="dialog-content"><nav class="drawer-links">${(corpus.programme?['wiki','research','programme','roadmap','books','repository','journal','docs']:['wiki','research','roadmap','books','repository','journal','docs']).map(p=>link(p,t(p),'','')).join('')}</nav><div class="drawer-settings">${localeSelect()}${themeBtn()}</div></div>`;d.setAttribute('aria-label',t('menu'));bindLanguagePickers(d);d.showModal()}
function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close())}
function setTheme(){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('cp-theme',theme)}catch{}document.querySelectorAll('.theme-btn').forEach(b=>{b.innerHTML=icon(theme==='dark'?'sun':'moon');b.setAttribute('aria-label',t(theme==='dark'?'light':'dark'))});document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#111c22':'#F7F6F1'}
function navigate(href,replace=false){closeDialogs();document.querySelectorAll('details[open]').forEach(d=>d.open=false);history[replace?'replaceState':'pushState']({},'',href);render();if(location.hash){document.getElementById(location.hash.slice(1))?.scrollIntoView()}else{window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true})};notifyAnalytics()}function notifyAnalytics(){try{if(window.CpAnalytics&&window.CpAnalytics.pageView)window.CpAnalytics.pageView();if(window.CpAnalytics&&window.CpAnalytics.refreshBanner)window.CpAnalytics.refreshBanner()}catch(error){}}
function bindFilters(){const input=document.querySelector('#reference-search');input?.addEventListener('input',e=>{if(!e.isComposing)applyFilter(undefined,e.target.value)});input?.addEventListener('compositionend',e=>applyFilter(undefined,e.target.value));document.querySelector('#page-search-form')?.addEventListener('submit',e=>{e.preventDefault();navigate(url('search')+'?q='+encodeURIComponent(new FormData(e.target).get('q')))})}
function applyFilter(type,query){const params=new URLSearchParams(location.search);if(type!==undefined){if(type==='all')params.delete('type');else params.set('type',type)}if(query!==undefined){if(query)params.set('q',query);else params.delete('q')}history.replaceState({},'',location.pathname+(params.size?'?'+params:''));const current=params.get('type')||'all';document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===current)));document.querySelector('#reference-results').innerHTML=referenceResults(current,params.get('q')||'')}
document.addEventListener('click',async e=>{const localeChoice=e.target.closest('[data-locale]');if(localeChoice){changeLocale(localeChoice.dataset.locale);return}if(!e.target.closest('.language-picker'))document.querySelectorAll('.language-picker[open]').forEach(d=>d.open=false);const search=e.target.closest('[data-search]');if(search){openSearch();return}if(e.target.closest('[data-menu]')){openMenu();return}if(e.target.closest('[data-close]')){e.target.closest('dialog').close();return}if(e.target.closest('.theme-btn')){setTheme();return}const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(JSON.stringify(example,null,2));copy.innerHTML=icon('check');copy.setAttribute('aria-label',t('copied'));document.querySelector('#announcement').textContent=t('copied');setTimeout(()=>{copy.innerHTML=icon('copy');copy.setAttribute('aria-label',t('copy'))},1600)}catch{document.querySelector('#announcement').textContent=t('copyFailed');const note=copy.closest('.code-window').querySelector('.code-note');note.textContent=t('copyFailed')}return}const filter=e.target.closest('[data-filter]');if(filter){applyFilter(filter.dataset.filter);return}if(e.target.closest('[data-clear]')){navigate(url('research'));return}const a=e.target.closest('a');if(a&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&a.target!=='_blank'&&a.origin===location.origin&&a.pathname!==location.pathname){if(isLabPath(a.pathname)||isLabPath(location.pathname))return;e.preventDefault();navigate(a.href)}if(!e.target.closest('.nav-group'))document.querySelectorAll('.nav-group').forEach(d=>d.open=false)});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&!e.target.matches('input,textarea,[contenteditable=true]')){e.preventDefault();openSearch()}if(e.key==='Escape'){document.querySelectorAll('.nav-group[open],.language-picker[open]').forEach(d=>{d.open=false;d.querySelector('summary').focus()})}});
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('close',()=>{if(lastTrigger?.isConnected)lastTrigger.focus()});d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close()})});
window.addEventListener('popstate',()=>{closeDialogs();render()});
const corpus=window.CP_CONTENT;
Object.assign(words,{referenceNotice:['A design reference from the original brief. This entry is separate from the published Knowledge Contract research.','Дизайн-референс исходного задания. Эта запись отделена от опубликованных исследований Knowledge Contract.','原始简报中的设计参考，与已发表的 Knowledge Contract 研究分开呈现。'],
 heroLabel:['Meaning management · Arcanada research','Управление смыслами · Исследования Arcanada','意义管理 · Arcanada 研究'],heroTitle:['Reuse knowledge. Keep its meaning.','Использовать знания. Сохранять смысл.','复用知识，保留意义。'],heroDesc:['Research on how people and agents can reuse knowledge while keeping its source, scope, evidence and conditions of use visible.','Исследуем, как люди и агенты могут использовать знания, сохраняя их источники, область применимости, основания и условия использования.','研究人类和智能体如何复用知识，同时保留其来源、范围、依据和使用条件。'],readResearch:['Explore the papers','Изучить работы','探索论文'],heroNote:['Knowledge Contract 3.0.0-draft.1 · Research in progress','Knowledge Contract 3.0.0-draft.1 · Исследование продолжается','Knowledge Contract 3.0.0-draft.1 · 研究进行中'],papers:['Papers','Научные работы','论文'],specs:['Specifications','Спецификации','规范'],scientificDraft:['Scientific draft','Научный черновик','科学草稿'],sourceArticles:['From the research journal','Статьи об исследовании','研究专栏'],releaseTitle:['The Meaning Management papers','Работы по управлению смыслами','意义管理论文'],releaseDesc:['Fourteen papers on sources, context, reasoning and the conditions of knowledge reuse.','Четырнадцать работ об источниках, контексте, рассуждениях и условиях повторного использования знаний.','十四篇论文，探讨来源、背景、推理及知识复用条件。'],statusNote:['Concept-level research with limited finite checks. Not an adopted standard or demonstrated product. Independent semantic review is still open.','Исследования на уровне концепций с ограниченными конечными проверками. Это не принятый стандарт и не подтверждённый продукт. Независимая семантическая проверка остаётся открытой.','概念层面的研究，包含有限检查。并非已采纳的标准或已验证的产品。独立语义审查尚未完成。'],readPaper:['Read the entry page','Читать описание работы','阅读概要'],englishEntry:['English summary','Английское резюме','英文概要'],russianOriginal:['Russian original','Русский оригинал','俄文原文'],fullArticle:['Read the full article on Arcanada','Полная статья на Arcanada','在 Arcanada 阅读全文'],publishedMaterial:['Published material','Опубликованные материалы','已发布材料'],readOriginal:['Open the original source','Открыть оригинальный источник','打开原始来源'],projectPurpose:['A research programme for the lifecycle of knowledge.','Исследовательская программа о жизненном цикле знаний.','研究知识生命周期。'],purposeText:['Knowledge Contract Arcana studies a unified contract for knowledge reuse: from sources and representations to bounded context, evidence, revisions and conditions of application. The published research is open; the processing engine remains proprietary.','Knowledge Contract Arcana исследует единый контракт повторного использования знаний: от источников и представлений к ограниченному контексту, основаниям, версиям и условиям применения. Опубликованные исследования открыты; обрабатывающий движок остаётся проприетарным.','Knowledge Contract Arcana 研究统一的知识复用契约：从来源与表示，到有界上下文、依据、版本和应用条件。已发表研究开放，处理引擎仍为专有。'],browseSpecs:['Browse specifications','Изучить спецификации','浏览规范'],researchIntro:['The first release: fourteen papers, with their claims, basis and limits intact.','Первый выпуск: четырнадцать работ с сохранением утверждений, оснований и ограничений.','首批十四篇论文，完整呈现主张、依据与局限。'],findReference:['Search papers…','Найти работу…','搜索论文…'],all:['All papers','Все работы','全部论文'],foundations:['Foundations','Основания','基础'],systems:['Systems & contracts','Системы и контракты','系统与契约'],evaluation:['Evaluation & reuse','Оценка и использование','评估与复用'],summaryNotice:['This is the original English entry page, not a full translation. The full Russian source is linked below.','Ниже — исходное английское резюме, а не полный перевод. Ссылка на полный русский оригинал находится ниже.','以下为原始英文概要，并非全文翻译。完整俄文原文链接见下方。'],sourceCredit:['By Pavel Valentov · Knowledge Contract Arcana · CC BY 4.0. Text retained; presentation adapted.','Павел Валентов · Knowledge Contract Arcana · CC BY 4.0. Текст сохранён; оформление адаптировано.','Pavel Valentov · Knowledge Contract Arcana · CC BY 4.0。保留文字，调整呈现方式。'],coverNote:['Editorial illustration; not an experimental result.','Редакционная иллюстрация; не результат эксперимента.','编辑插图，并非实验结果。'],articleFigure:['Original figure from the source publication. Read its scientific status in the original article.','Оригинальная иллюстрация из публикации. Её научный статус описан в исходной статье.','原始出版物中的图示。其科学状态请参阅原文。'],journalDesc:['Two published articles on Knowledge Contract architecture and its second version.','Две опубликованные статьи об архитектуре Knowledge Contract и её второй версии.','两篇已发表文章，介绍 Knowledge Contract 架构及其第二版。'],specIntro:['Ten draft specifications that the published papers rely on. Each retains its identity, status, claims and limits.','Десять черновых спецификаций, на которые опираются опубликованные работы. Сохранены их идентичность, статус, утверждения и ограничения.','十份论文所依据的规范草案，保留各自标识、状态、主张与局限。'],publicSearch:['Search the published documents','Поиск по опубликованным документам','搜索已发布文档'],publicSearchDesc:['The public read API searches published passages with source, revision, status and licence. Open the full-document search on this site.','Публичный API ищет опубликованные фрагменты с источником, версией, статусом и лицензией. Откройте поиск по полному тексту на этом сайте.','公共只读 API 搜索已发布段落，并显示来源、版本、状态和许可。可在本站打开全文搜索。'],openDocumentSearch:['Open document search','Открыть поиск по документам','打开文档搜索'],integrationDesc:['The project already exposes a public read API and an MCP endpoint. These access routes do not establish scientific validity or grant action rights.','У проекта уже есть публичный API чтения и MCP endpoint. Доступ к материалам не подтверждает научную состоятельность и не даёт прав на действия.','项目已提供公共只读 API 和 MCP 端点。访问材料不代表科学验证，也不授予行动权限。'],publicAPI:['Public read API','Публичный API чтения','公共只读 API'],apiDesc:['Search, related and fetch routes over published documents. Health and search responded during this update.','Маршруты search, related и fetch по опубликованным документам. Health и search ответили при этом обновлении.','针对已发布文档的 search、related 和 fetch 路由。此次更新已收到 health 和 search 响应。'],mcpDesc:['The source site reports an initialize response on 3 November 2026. This website does not register a new MCP server.','Исходный сайт сообщает об ответе initialize 3 ноября 2026 года. Этот сайт не регистрирует новый MCP-сервер.','原网站报告于 2026 年 11 月 3 日收到 initialize 响应。本站不注册新的 MCP 服务器。'],docsIntro:['Read the specifications, inspect source records and access published documents.','Читайте спецификации, проверяйте исходные записи и находите опубликованные документы.','阅读规范、检查来源记录并访问已发布文档。'],localSearchDesc:['The site search finds the 14 papers, 10 specifications and two articles in this edition. Full-document search is available on contract.place.','Поиск сайта находит 14 работ, 10 спецификаций и две статьи этой редакции. Поиск по полным документам доступен на contract.place.','本站搜索可查找本版的 14 篇论文、10 份规范和两篇文章。全文搜索可在 contract.place 使用。'],searchPlaceholder:['Search papers, specifications and articles…','Искать работы, спецификации и статьи…','搜索论文、规范和文章…'],searchStart:['Try “context”, “evidence” or “contract”.','Попробуйте «контекст», «основания» или «контракт».','试试“context”、“evidence”或“contract”。'],repositoryIntro:['Published source records, with stable artifact identifiers and entry-page revisions.','Опубликованные записи с постоянными идентификаторами артефактов и версиями резюме.','已发布来源记录，包含稳定的制品标识与概要版本。'],sourceRepo:['Source repository','Исходный репозиторий','源代码仓库'],licensing:['Use and cite','Использование и цитирование','使用与引用'],openWork:['Open research. Explicit limits.','Открытое исследование. Явные ограничения.','开放研究，明确局限。'],licenseText:['Text is CC BY 4.0; code is Apache-2.0. Keep author, source and upstream credits when reusing material.','Текст — CC BY 4.0; код — Apache-2.0. При использовании сохраняйте указание автора, источника и сторонних материалов.','文字采用 CC BY 4.0，代码采用 Apache-2.0。复用时请保留作者、来源及上游署名。'],wikiIntro:['Start with the published work behind the key ideas. These paths lead to source-backed research, not illustrative placeholder concepts.','Начните с опубликованных работ, на которых основаны ключевые идеи. Эти пути ведут к исследованиям с источниками.','从关键概念背后的已发表研究开始。这些路径通向有来源依据的研究。'],footerNote:['Knowledge Contract Arcana · Arcanada ecosystem','Knowledge Contract Arcana · Экосистема Arcanada','Knowledge Contract Arcana · Arcanada 生态系统'],references:['Design references','Дизайн-референсы','设计参考'],sourceStatus:['Publication status','Статус публикации','出版状态'],articleAbstract:['From the original abstract','Из исходной аннотации','摘自原始摘要'],viewAllPapers:['All 14 papers','Все 14 работ','全部 14 篇论文'],viewAllSpecs:['All 10 specifications','Все 10 спецификаций','全部 10 份规范']
});
function cover(r,cls='',lazy=true){return `<img class="editorial-image ${cls}" src="/assets/${r.image}" alt="" width="1200" height="800" ${lazy?'loading="lazy"':''} decoding="async">`}
function journalCard(a){return `<article class="journal-card"><a class="journal-cover" href="${url('journal/'+a.id)}" aria-label="${esc(a.title)}"><img src="/assets/${a.id.includes('architecture')?'knowledge-prism.webp':'knowledge-dialogue.webp'}" alt="" width="1200" height="800" loading="lazy"></a><div class="journal-copy"><span class="tag">${t('publishedMaterial')}</span><h3><a href="${url('journal/'+a.id)}">${esc(a.title)}</a></h3><p>${esc(a.description)}</p><div class="metadata"><span>Pavel Valentov</span><span>Arcanada</span></div>${link('journal/'+a.id,t('readEntry'))}</div></article>`}
function journal(){return `<div class="container">${pageHead(t('journal'),t('journalDesc'))}<div class="journal-grid journal-index">${corpus.articles.map(a=>journalCard(a).replace(/<(\/?)h3>/g,'<$1h2>')).join('')}</div></div>`}
function publication(a){const coverName=a.id.includes('architecture')?'knowledge-prism.webp':'knowledge-dialogue.webp';return `<div class="container source-record"><div class="page-head"><div class="breadcrumb">${link('journal',t('journal'),'','')}<span>/</span><span>Arcanada</span></div><span class="tag">${t('publishedMaterial')}</span><h1 lang="en">${esc(a.title)}</h1><p class="lead" lang="en">${esc(a.description)}</p><div class="provenance metadata"><span>Pavel Valentov</span><span>Knowledge Contract Arcana</span><span>CC BY 4.0</span></div><a class="button" href="${a.source}" target="_blank" rel="noopener">${t('fullArticle')}${icon('external')}</a></div><figure class="article-cover"><img src="/assets/${coverName}" width="1200" height="800" alt="" decoding="async"><figcaption>${t('coverNote')}</figcaption></figure><article class="publication-body"><section class="publication-status"><h2>${t('sourceStatus')}</h2><div lang="en">${a.status.split('\n\n').slice(1).map(p=>`<p>${esc(p)}</p>`).join('')}</div></section><h2>${t('articleAbstract')}</h2><div lang="en">${a.abstract.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}</div><figure class="scientific-figure"><a href="${a.source}" target="_blank" rel="noopener"><img src="/assets/${a.image}" alt="${esc(a.id.includes('architecture')?'Original schematic of knowledge sources, the Resolver, Knowledge Contract and execution':'Original illustration of typed knowledge blocks and a receiving agent schema')}" loading="lazy"></a><figcaption>${t('articleFigure')}</figcaption></figure><p class="attribution">${t('sourceCredit')}</p><a class="button" href="${a.source}" target="_blank" rel="noopener">${t('fullArticle')}${icon('external')}</a></article></div>`}
function docs(path){if(path==='docs/availability')return `<div class="container"><div class="reading">${pageHead(t('availability'),t('integrationDesc'))}<div class="status-row"><div><strong>${t('publicAPI')}</strong><p>${t('apiDesc')}</p><a class="text-link" href="https://api.contract.place/health" target="_blank" rel="noopener">api.contract.place/health ${icon('external')}</a></div><span class="tag">${t('available')}</span></div><pre class="endpoint-code"><code>GET https://api.contract.place/v1/search?q=knowledge&limit=10\nGET https://api.contract.place/v1/related\nGET https://api.contract.place/v1/fetch</code></pre><p class="intro-note">${translated(['Only the search request above is complete. Related and fetch require their documented parameters. The API accepts browser requests only from contract.place; this site’s document search uses it, other origins should use an HTTP client.','Только запрос search выше приведён полностью. Для related и fetch нужны параметры из документации. API принимает запросы из браузера только с contract.place; поиск по документам на этом сайте использует его, с других источников обращайтесь HTTP-клиентом.','上方仅 search 请求为完整示例。related 和 fetch 需要其文档中的参数。API 仅接受来自 contract.place 的浏览器请求；本站文档搜索使用该接口，其他来源请使用 HTTP 客户端。'])}</p><a class="button" href="${url('search')}#document-search">${t('openDocumentSearch')}${icon('arrow')}</a><div class="status-row"><div><strong>MCP</strong><p>${t('mcpDesc')}</p><code>https://api.contract.place/mcp</code></div></div><div class="status-row"><div><strong>${t('account')}</strong><p>${t('accountDesc')}</p></div><span class="status">${t('notConnected')}</span></div></div></div>`;return `<div class="container">${pageHead(t('specs'),t('specIntro'))}<div class="docs-banner"><div><h2>${t('knowledgeModel')}</h2><p>${t('integrationDesc')}</p>${link('docs/availability',t('availability'))}</div><img src="/assets/knowledge-landscape.webp" alt="" width="500" height="280" loading="lazy"></div><p class="intro-note">${t('statusNote')}</p><div class="spec-list">${corpus.records.filter(r=>r.kind==='spec').map(r=>`<a class="spec-row" href="${url(recordPath(r))}"><div class="card-icon">${icon('file')}</div><div><h2>${esc(recordTitle(r))}</h2><div class="metadata"><span>${r.artifact}</span><span>${t('scientificDraft')}</span></div></div>${icon('arrow')}</a>`).join('')}</div></div>`}
function about(){return `<article class="container reading">${pageHead(t('licensing'),t('licenseText'))}<h2>Knowledge Contract Arcana</h2><p>${t('purposeText')}</p><h2>CC BY 4.0</h2><p lang="en">Text by Pavel Valentov, Knowledge Contract Arcana, <a href="https://contract.place/" target="_blank" rel="noopener">contract.place</a>, licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. The canonical publication texts are compiled from the pinned source revision. The interface language does not change the English source text. Original editorial cover illustrations were generated for this website and are not scientific diagrams. Original scientific figures retain their source attribution.</p><h2>Apache-2.0</h2><p lang="en">Published source code is available in the <a href="https://github.com/Arcanada-one/knowledge-contract" target="_blank" rel="noopener">knowledge-contract repository</a>. Retain its NOTICE, licence and upstream credits when reusing it.</p><ul class="source-list"><li><a href="https://github.com/Arcanada-one/knowledge-contract/blob/main/ATTRIBUTION.md" target="_blank" rel="noopener">Attribution guidance ${icon('external')}</a></li><li><a href="https://arcanada.ai/en/ecosystem/contract-place" target="_blank" rel="noopener">Arcanada project page ${icon('external')}</a></li></ul><h2>${t('privacy')}</h2><p>${t('localSearchDesc')}</p><h2>${t('analyticsTitle')}</h2><p>${t('analyticsBody')}</p><p><a href="https://policies.google.com/privacy" target="_blank" rel="noopener">Google Privacy &amp; Terms ${icon('external')}</a></p></article>`}
function footer(){return `<div class="container"><div class="footer-grid"><div class="footer-brand">${brand()}<p>${t('tagline')}</p><p class="ecosystem-note">${translated(['Knowledge Contract Arcana is part of the Arcanada ecosystem.','Knowledge Contract Arcana — часть экосистемы Arcanada.','Knowledge Contract Arcana 是 Arcanada 生态系统的一部分。'])}</p><a class="ecosystem-link" href="https://arcanada.ai" target="_blank" rel="noopener">Arcanada ${icon('external')}</a></div><div class="footer-group"><strong>${t('research')}</strong>${link('research',t('papers'),'','')}${corpus.programme?link('programme',t('programme'),'',''):''}${link('roadmap',t('roadmap'),'','')}${link('journal',t('journal'),'','')}${link('reference',t('reference'),'','')}${link('appendices',t('appendices'),'','')}</div><div class="footer-group"><strong>${t('developers')}</strong>${link('engineering/specifications',t('specs'),'','')}${link('engineering/studies',t('studies'),'','')}${link('repository',t('repository'),'','')}${link('docs/availability',t('availability'),'','')}${link('lab/knowledge-journey',t('labTitle'),'','')}</div><div class="footer-group"><strong>contract.place</strong>${link('about',t('licensing'),'','')}<a href="${url('search')}#document-search">${t('publicSearch')}</a>${link('references',t('references'),'','')}<button type="button" class="footer-consent" data-consent-settings>${t('cookieSettings')}</button></div></div><div class="footer-bottom"><span>© 2026 Pavel Valentov · ${t('footerNote')}</span><span>${translated(['Content CC BY 4.0, code Apache-2.0.','Контент CC BY 4.0, код Apache-2.0.','内容 CC BY 4.0，代码 Apache-2.0。'])}</span></div>${locale==='zh-Hans'?'<p class="footer-credit zh-notice" lang="zh-Hans">中文界面尚未经过母语编辑审校。</p>':''}<p class="footer-credit" lang="en">Credit: Knowledge Contract Arcana, <a href="https://contract.place">https://contract.place</a>. <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a> · <a href="https://www.apache.org/licenses/LICENSE-2.0" target="_blank" rel="noopener">Apache-2.0</a> · <a href="https://github.com/Arcanada-one/knowledge-contract/blob/main/ATTRIBUTION.md" target="_blank" rel="noopener">Attribution</a></p></div>`}
function referencesPage(){return `<div class="container">${pageHead(t('references'),translated(['The six visual and structural references from the original design brief.','Шесть визуальных и структурных референсов исходного задания.','原始设计简报中的六个视觉与结构参考。']))}<div class="records">${refs.map(r=>`<a class="record" href="${r.source}" target="_blank" rel="noopener"><div><h2>${r.name}</h2><p>${translated(r.desc)}</p></div>${icon('external')}</a>`).join('')}</div></div>`}

