function research(){
const q=new URLSearchParams(location.search),type=q.get('type')||'all',query=q.get('q')||'';
return `<div class="container">${pageHead(t('research'),t('researchIntro'))}<p class="intro-note">${t('statusNote')}</p><div class="filter-bar">${['all','foundations','systems','evaluation'].map(x=>filterButton(x,t(x),type)).join('')}<input class="search-input" id="reference-search" type="search" placeholder="${t('findReference')}" aria-label="${t('findReference')}" value="${esc(query)}"></div><div id="reference-results">${referenceResults(type,query)}</div></div>`;
}
function referenceResults(type,query){
const all=corpus.records.filter(r=>r.kind==='paper'),items=all.filter(r=>(type==='all'||paperCategory(r)===type)&&normalize(r.title+' '+r.summary+' '+r.id).includes(normalize(query)));
return `<div class="result-count">${items.length} / ${all.length}</div><div class="paper-grid catalog-grid">${items.map(r=>paperCard(r).replace(/<(\/?)h3>/g,'<$1h2>')).join('')}</div>${items.length?'':`<div class="empty"><h2>${t('noResults')}</h2><button class="button" data-clear>${t('clear')}</button></div>`}`;
}
function publicationList(kinds,title,intro){
const records=corpus.records.filter(r=>kinds.includes(r.kind));
return `<div class="container">${pageHead(t(title),t(intro))}<div class="spec-list">${records.map(r=>`<a class="spec-row" href="${url(recordPath(r))}"><div class="card-icon">${icon('file')}</div><div><h2 lang="en">${esc(r.title)}</h2><p lang="en">${esc(r.summary)}</p><div class="metadata"><span>${recordLabel(r)}</span><span>${t('englishText')}</span>${statusBadge(r)}</div></div>${icon('arrow')}</a>`).join('')}</div></div>`;
}
function engineering(){
return `<div class="container">${pageHead(t('docs'),t('engineeringIntro'))}<div class="publication-sections"><a class="record" href="${url('engineering/specifications')}"><div><h2>${t('specs')}</h2><p>${t('specIntro')}</p></div>${icon('arrow')}</a><a class="record" href="${url('engineering/studies')}"><div><h2>${t('studies')}</h2><p>${t('studyIntro')}</p></div>${icon('arrow')}</a></div><p class="intro-note">${t('integrationDesc')} ${link('appendices/api-integration',t('availability'))}</p></div>`;
}
function wiki(){return publicationList(['glossary','bibliography'],'reference','referenceIntro');}
function sourceRecord(r){
const family=recordPath(r).split('/').slice(0,-1).join('/'),familyLabel=recordLabel(r),siblings=corpus.records.filter(s=>s.kind===r.kind);
const cited='Pavel Valentov. '+r.title+'. Knowledge Contract Arcana, edition '+corpus.publication.edition+'.';
return `<div class="container source-record publication-record"><div class="page-head"><nav class="breadcrumb" aria-label="Breadcrumb">${link('',t('home'),'','')}<span>/</span>${link(family,familyLabel,'','')}</nav><div class="metadata"><span>${familyLabel}</span><span>${t('publicationEdition')} ${esc(corpus.publication.edition)}</span>${statusBadge(r)}</div><h1 id="${esc(r.title_id)}" lang="en">${esc(r.title)}</h1><p class="lead" lang="en">${esc(r.summary)}</p><div class="provenance metadata"><span>Pavel Valentov</span><span>CC BY 4.0</span><span>${t('englishText')}</span></div><div class="actions"><a class="text-link" href="${r.source}" target="_blank" rel="noopener">${t('fullSource')}${icon('external')}</a><a class="text-link" href="${r.history}" target="_blank" rel="noopener">${t('history')}${icon('external')}</a></div><p class="reading-language-note">${t('readingNotice')}</p>${statusNote(r)}</div>
<div class="source-reading"><article><div class="source-body prose" lang="en">${r.html}</div><section class="document-citation" aria-label="Citation"><h2>${t('citation')}</h2><p lang="en">${esc(cited)} <a href="https://contract.place${r.route}">https://contract.place${r.route}</a>. Source revision <code>${r.revision}</code>.</p><p>${t('sourceCredit')}</p></section></article><aside class="article-aside"><details class="reader-contents" open><summary>${t('contents')}</summary><nav aria-label="${t('contents')}">${r.toc.map(h=>`<a class="toc-level-${h.level}" href="#${esc(h.id)}" lang="en">${esc(h.title)}</a>`).join('')}</nav></details><hr><strong>${familyLabel}</strong>${siblings.map(s=>`<a href="${url(recordPath(s))}"${s.id===r.id?' aria-current="page"':''} lang="en">${esc(s.title)}${statusBadge(s)}</a>`).join('')}<hr>${link('reference/glossary',t('reference'),'','')}${link('appendices/source-map',t('sourceMap'),'','')}</aside></div></div>`;
}
function compatibilityPage(path){
const record=corpus.records.find(r=>recordPath(r)===corpus.aliases[path]);
if(!record)throw new Error('Compatibility route has no target: '+path);
return `<article class="container reading">${pageHead(t('compatibility'),t('compatibilityText'))}<h2 lang="en">${esc(record.title)}</h2><p lang="en">${esc(record.summary)}</p>${link(recordPath(record),t('readPaper'),'button')}<p>${link('appendices/source-map',t('sourceMap'))}</p></article>`;
}
function roadmapName(id){const road=corpus.roadmap,task=road.tasks.find(k=>k.id===id);if(!task)return id;return locale==='ru'?(task.display_name_ru||task.display_name||id):(task.display_name||id)}
function roadmapIds(ids){return ids.length?ids.map(i=>`<a href="#${i.toLowerCase()}"><span lang="${locale==='ru'?'ru':'en'}">${esc(roadmapName(i))}</span></a>`).join(', '):t('roadmapNone')}
function roadmapTable(road){
const head=['roadmapTask','roadmapPriority','roadmapOwner','roadmapStatus','roadmapRequires','roadmapNeededBy','roadmapInforms','roadmapInformedBy'].map(k=>`<th scope="col">${t(k)}</th>`).join('');
const rows=road.tasks.map(k=>`<tr data-task-id="${k.id}"><th scope="row"><a href="#${k.anchor}"><span lang="${locale==='ru'?'ru':'en'}">${esc(roadmapName(k.id))}</span></a></th><td>${esc(k.priority_label||k.priority)}</td><td lang="en">${esc(k.owner)}</td><td>${t('roadmapPlannedStatus')}</td><td>${roadmapIds(k.requires)}</td><td>${roadmapIds(k.needed_by)}</td><td>${roadmapIds(k.informs)}</td><td>${roadmapIds(k.informed_by)}</td></tr>`).join('');
return `<div class="table-scroll roadmap-table" role="region" aria-label="${t('roadmapTableLabel')}" tabindex="0"><table><caption>${t('roadmapTableLabel')}</caption><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table></div>`;
}
function roadmapCard(k){
const rel=[['roadmapRequires',k.requires],['roadmapNeededBy',k.needed_by],['roadmapInforms',k.informs],['roadmapInformedBy',k.informed_by]].filter(([,v],i)=>i<2||v.length).map(([key,v])=>`<div><dt>${t(key)}${key==='roadmapInforms'||key==='roadmapInformedBy'?` <small>(${t('roadmapInformsNoBlock')})</small>`:''}</dt><dd>${roadmapIds(v)}</dd></div>`).join('');
const name=roadmapName(k.id);
const subtitle=k.subtitle?` <span class="rm-subtitle" lang="en">${esc(k.subtitle)}</span>`:'';
return `<article class="roadmap-card" id="${k.anchor}" data-task-id="${k.id}" aria-labelledby="${k.anchor}-title"><h3 id="${k.anchor}-title"><a class="rm-name" href="#${k.anchor}" lang="${locale==='ru'?'ru':'en'}">${esc(name)}</a>${subtitle}</h3><div class="metadata"><span>${t('roadmapPriority')}: ${esc(k.priority_label||k.priority)}</span><span>${t('roadmapOwner')}: <span lang="en">${esc(k.owner)}</span></span><span class="rm-status">${t('roadmapStatus')}: ${t('roadmapPlannedStatus')}</span></div><dl class="roadmap-relations">${rel}</dl><dl class="roadmap-fields" lang="en">${k.fields.map(f=>`<div><dt>${esc(f.label)}</dt><dd class="source-body prose">${localizeCatalogueLinks(f.html)}${roadmapLinkedStatus(f.html)}</dd></div>`).join('')}</dl></article>`;
}
function roadmapPage(){
const road=corpus.roadmap,pin=road.pin,ms=corpus.publication.commit,same=pin.commit===ms;
const bands=['P0','P1','P2'].map(b=>{const label=(road.priority_labels&&road.priority_labels[b])||b;return `<div class="roadmap-band"><h3 lang="en">${esc(label)}</h3><ul>${road.tasks.filter(k=>k.priority===b).map(k=>`<li><a href="#${k.anchor}"><span lang="${locale==='ru'?'ru':'en'}">${esc(roadmapName(k.id))}</span></a></li>`).join('')}</ul></div>`;}).join('');
const advisory=`<div class="table-scroll roadmap-table" role="region" aria-label="${t('roadmapAdvisoryLabel')}" tabindex="0"><table><caption>${t('roadmapAdvisoryLabel')}</caption><thead><tr><th scope="col">${t('roadmapFrom')}</th><th scope="col">${t('roadmapTo')}</th><th scope="col">${t('roadmapRelation')}</th></tr></thead><tbody>${road.advisory.map(a=>`<tr data-from="${a.from}" data-to="${a.to}"><td><a href="#${a.from.toLowerCase()}"><span lang="${locale==='ru'?'ru':'en'}">${esc(roadmapName(a.from))}</span></a></td><td><a href="#${a.to.toLowerCase()}"><span lang="${locale==='ru'?'ru':'en'}">${esc(roadmapName(a.to))}</span></a></td><td>${t('roadmapInformsNoBlock')}</td></tr>`).join('')}</tbody></table></div>`;
const files=`<div class="table-scroll roadmap-table" role="region" aria-label="${t('roadmapFilesLabel')}" tabindex="0"><table><caption>${t('roadmapFilesLabel')}</caption><thead><tr><th scope="col">${t('roadmapFile')}</th><th scope="col">${t('roadmapRole')}</th><th scope="col">SHA-256</th></tr></thead><tbody>${pin.files.map(f=>`<tr><td><a href="${f.url}" target="_blank" rel="noopener"><code>${esc(f.path)}</code></a></td><td lang="en">${esc(f.role)}</td><td><code class="hash">${f.sha256}</code></td></tr>`).join('')}</tbody></table></div>`;
const sections=[['roadmap-overview','roadmapOverview'],['roadmap-bands','roadmapBands'],['roadmap-dependencies','roadmapDependencies'],['roadmap-advisory','roadmapAdvisory'],['roadmap-tasks','roadmapTasks'],['roadmap-source','roadmapSources']];
const toc=sections.map(([id,key])=>`<a class="toc-level-2" href="#${id}">${t(key)}</a>`).join('')+road.overview_toc.map(h=>`<a class="toc-level-3" href="#${esc(h.id)}" lang="en">${esc(h.title)}</a>`).join('')+road.tasks.map(k=>`<a class="toc-level-3 toc-task" href="#${k.anchor}"><span lang="${locale==='ru'?'ru':'en'}">${esc(roadmapName(k.id))}</span></a>`).join('');
return `<div class="container source-record publication-record roadmap-page"><div class="page-head"><nav class="breadcrumb" aria-label="Breadcrumb">${link('',t('home'),'','')}<span>/</span><span>${t('roadmap')}</span></nav><div class="metadata"><span class="tag">${t('roadmapPlanned')}</span><span>${road.tasks.length} ${t('roadmapCounts')}</span><span>${road.required_edges} ${t('roadmapRequiredEdges')}</span><span>${road.advisory.length} ${t('roadmapAdvisoryEdges')}</span></div><h1>${t('roadmap')}</h1><p class="lead" lang="en">${esc(road.introduction)}</p><p class="roadmap-notice" role="note">${t('roadmapStatusNote')}</p><p class="reading-language-note">${t('roadmapLanguageNote')}</p><div class="provenance metadata"><span>${t('roadmapRoadmapCommit')}: <a href="https://github.com/${pin.repository}/tree/${pin.commit}"><code>${pin.commit}</code></a></span><span>${t('roadmapManuscriptCommit')}: <a href="https://github.com/Arcanada-one/knowledge-contract/tree/${ms}"><code>${ms}</code></a></span></div></div>
<div class="source-reading"><article class="roadmap-body"><section aria-labelledby="roadmap-overview" id="roadmap-section-overview"><h2 id="roadmap-overview">${t('roadmapOverview')}</h2><div class="source-body prose" lang="en">${road.overview_html}</div></section>
<section aria-labelledby="roadmap-bands"><h2 id="roadmap-bands">${t('roadmapBands')}</h2><div class="roadmap-bands">${bands}</div></section>
<section aria-labelledby="roadmap-dependencies"><h2 id="roadmap-dependencies">${t('roadmapDependencies')}</h2><p>${t('roadmapDepsIntro')}</p>${roadmapTable(road)}</section>
<section aria-labelledby="roadmap-advisory"><h2 id="roadmap-advisory">${t('roadmapAdvisory')}</h2>${advisory}</section>
<section aria-labelledby="roadmap-tasks"><h2 id="roadmap-tasks">${t('roadmapTasks')}</h2><div class="source-body prose" lang="en">${road.tasks_intro_html}</div>${road.tasks.map(roadmapCard).join('')}</section>
<section class="document-citation" aria-labelledby="roadmap-source"><h2 id="roadmap-source">${t('roadmapSources')}</h2><p>${same?t('roadmapPinsSame'):t('roadmapPinsDiffer')}</p><div class="metadata"><span>${t('roadmapDefRevision')}: <code>${esc(road.revision)}</code></span><span>${t('roadmapBaseline')}: <code>${esc(road.baseline_commit)}</code></span><span>${t('roadmapEdition')} (${t('roadmapManuscriptCommit')}): ${esc(corpus.publication.edition)}</span></div><p lang="en"><strong>${t('roadmapExecution')}:</strong> ${esc(road.execution_bindings)}</p>${files}<p><a href="/roadmap.json">roadmap.json</a></p></section></article>
<aside class="article-aside"><details class="reader-contents" open><summary>${t('roadmapContents')}</summary><nav aria-label="${t('roadmapContents')}">${toc}</nav></details></aside></div></div>`;
}
function programmePage(){
const prog=corpus.programme;if(!prog||!prog.pages||!prog.pages[locale])throw new Error('Programme guide missing for '+locale);
const page=prog.pages[locale],pin=prog.pin;
const switcher=['en','ru','zh-Hans'].map(l=>{const p=prog.pages[l];const label={en:'English',ru:'Русский','zh-Hans':'简体中文'}[l];return l===locale?`<span class="lang-current" aria-current="page" lang="${l}">${label}</span>`:`<a href="${p.route}" hreflang="${l}" lang="${l}">${label}</a>`;}).join(' · ');
const cards=page.foundations.map((c,i)=>`<article class="foundation-card" data-foundation="${i+1}"><h3 lang="${locale}">${esc(c.title)}</h3><p lang="${locale}">${c.html||esc(c.visible||c.text)}</p></article>`).join('');
const files=pin.files.map(f=>`<tr><td><a href="${f.url}" target="_blank" rel="noopener"><code>${esc(f.path)}</code></a></td><td><code class="hash">${f.sha256}</code></td><td><code>${f.blob}</code></td></tr>`).join('');
return `<div class="container source-record publication-record programme-page"><div class="page-head"><nav class="breadcrumb" aria-label="Breadcrumb">${link('',t('home'),'','')}<span>/</span><span>${t('programme')}</span></nav><div class="metadata"><span class="tag">${t('programme')}</span><span>${t('programmeLanguageSwitch')}: ${switcher}</span></div><h1 id="${esc(page.title_id)}" lang="${locale}">${esc(page.title)}</h1><p class="reading-language-note">${t('programmeReadingNote')}</p><div class="provenance metadata"><span>${t('source')}: <a href="${page.source}" target="_blank" rel="noopener"><code>${esc(page.path)}</code></a></span><span>commit <a href="https://github.com/${pin.repository}/tree/${pin.commit}"><code>${pin.commit}</code></a></span><span>blob <code>${page.blob}</code></span><span>SHA-256 <code class="hash">${page.source_sha256}</code></span></div></div>
<section class="programme-foundations" aria-labelledby="programme-foundations"><h2 id="programme-foundations">${t('programmeFoundations')}</h2><div class="foundation-grid">${cards}</div></section>
<div class="source-reading"><article><div class="source-body prose" lang="${locale}">${page.html}</div><section class="document-citation" aria-labelledby="programme-source"><h2 id="programme-source">${t('programmeSources')}</h2><p>Arcanada-one/knowledge-contract @ <code>${pin.commit}</code></p><div class="table-scroll" role="region" tabindex="0"><table><thead><tr><th scope="col">path</th><th scope="col">SHA-256</th><th scope="col">blob</th></tr></thead><tbody>${files}</tbody></table></div></section></article><aside class="article-aside"><details class="reader-contents" open><summary>${t('contents')}</summary><nav aria-label="${t('contents')}">${page.toc.map(h=>`<a class="toc-level-${h.level}" href="#${esc(h.id)}" lang="${locale}">${esc(h.title)}</a>`).join('')}</nav></details><hr><strong>${t('programmeLanguageSwitch')}</strong><div class="programme-langs">${switcher}</div></aside></div></div>`;
}
