function searchItems(q){
const items=[...corpus.records.map(r=>({title:r.title,desc:r.summary+' '+r.id,type:recordLabel(r),badge:statusBadge(r),path:recordPath(r)})),...corpus.articles.map(a=>({title:a.title,desc:a.description,type:t('journal'),path:'journal/'+a.id})),{title:t('availability'),desc:t('integrationDesc'),type:t('docs'),path:'docs/availability'},...(corpus.programme?[{title:t('programme'),desc:t('programmeDesc'),type:t('programme'),path:'programme'}]:[]),{title:t('roadmap'),desc:t('roadmapDesc'),type:t('roadmap'),path:'roadmap'}];
return items.filter(x=>normalize(x.title+' '+x.desc+' '+x.type).includes(normalize(q)));
}
